    a_m &= -\frac{(n-m)(n-m-1)}{m} a_{m-1}\, ,\qquad a_0 =1 \\
    F_{m-1}(\lambda) &= \der_\lambda F_m(\lambda)\, ,\qquad  F_{n-1} (\lambda) = \frac{1}{n!} \lambda(\lambda^2+1)^{n-\frac12} \, .
