\label{Shannon}
\end{equation}
with the normalization condition:
\begin{equation}
\sum_{n=1}^N \sum_{j=1}^{{\mathcal N_C}(n)} P(\tau_j,n)= 1 \hspace{5pt}.
\end{equation}
