\section{The Hamiltonian}\label{sec:Hamiltonian}
Consider a system of fermions and let $c_{\alpha j},\, c_{\alpha' k}^\dagger$, $\alpha, \alpha' \in \{+, -\}$, $j,k \in 1,2,\dots,L$ denote the annihilation and creation operators, satisfying
\begin{equation*}
    \{ c_{\alpha j}, c_{\alpha' k} \} = \{ c_{\alpha j}^\dagger , c_{\alpha' k}^\dagger \} = 0, \qquad \{ c_{\alpha j}^\dagger, c_{\alpha' k} \} = \delta_{\alpha \alpha'} \delta_{jk}.
\end{equation*}
We consider the following integrable BCS Richardson-Gaudin Hamiltonian reported in \cite{Skryp19},
\begin{align} \nonumber
	H_{BCS} & = \frac{1}{2} \sum_{i=1}^L f_i^+ f_i^- ( c^\dagger_{+i} c_{+i} + c^\dagger_{-i} c_{-i} ) + \sum_{i=1}^L \left( f^-_i \gamma - \mi f^+_i \lambda \right) c^\dagger_{+i} c^\dagger_{-i} \\ \nonumber
	& \qquad + \sum_{i=1}^L \left( f^-_i \gamma + \mi f^+_i \lambda \right) c_{-i} c_{+i} + \frac{g}{2} \sum_{i=1}^L \sum_{j\neq i}^L \big( f^-_i f^-_j + f^+_i f^+_j  \big) c^\dagger_{+i} c^\dagger_{-i} c_{-j} c_{+j} \\ \label{eq:Hamiltonian}
	& \qquad + \frac{g}{4} \sum_{i=1}^L \sum_{j\neq i}^L \big( f^-_i f^-_j - f^+_i f^+_j  \big) \big(c^\dagger_{+i} c^\dagger_{-i} c^\dagger_{+j} c^\dagger_{-j} + c_{-i} c_{+i} c_{-j} c_{+j} \big),
\end{align}
where $g,\gamma,\lambda\in\mathbb{R}$ and
\begin{align} \label{eq:cov1}
	f_k^+ & = \sqrt{\epsilon_k + \beta_x}, \quad f_k^-  = \sqrt{\epsilon_k + \beta_y},
\end{align}
with $\epsilon_k>0$, $\epsilon_k + \beta_x >0$ and $\epsilon_k + \beta_y >0$ for all $k=1,\dots,L$. Assuming $\beta_x > \beta_y$ and setting
$$ z_k^2 = \epsilon_k + \frac{\beta_x + \beta_y}{2}, \quad \beta = \frac{\beta_x - \beta_y}{2}, $$
we have $$ f_k^+ = \sqrt{z_k^2 + \beta}, \quad f_k^- = \sqrt{z_k^2 - \beta}.$$
This Hamiltonian $H_{BCS}$ in \eqref{eq:Hamiltonian} is a generalisation of the open $p+ip$ Hamiltonian \cite{LIL16}.

