c=\sqrt{\frac{g_{\rm B}n_{0}}{m_{\rm B}}},
\end{equation}
is the speed of sound in the BEC. Finally, $n_{0}$ is the density
of the bath particles in the ground state, which turns out to be constant as a result of the homogeneity of the BEC. 
%which we assume to be constant in space, i.e. we are considering a homogeneous BEC gas. 
For a macroscopically occupied condensate, i.e. $N_{j\neq0}\ll N_{0}$ where $N_{j}$ is the occupation number of the $j^{th}$ state, we obtain the following expression for the interaction part of the Hamiltonian 
\begin{equation}
H_{\rm IB}^{(j)}=n_{0}V_{\rm IB}^{(j)}+\sqrt{\frac{n_{0}}{V}}\sum_{{\bf k}\neq0}\rho_{\rm I}^{(j)}\left({\bf k}\right)V_{\rm IB}^{(j)}\left(a_{{\bf k}}+a_{-{\bf k}}^{\dagger}\right),
\end{equation}
which after the Bogoliubov transformation, becomes
\begin{equation}
H_{\rm IB}^{(j)}=\sum_{{\bf k}\neq0}V_{{\bf k}}^{(j)}e^{i{\bf k}\left(x_{j}+d_{j}\right)}\left(b_{{\bf k}}+b_{-{\bf k}}^{\dagger}\right).
\end{equation}
Here, the couplings are
\begin{equation}
V_{{\bf k}}^{(j)}=g_{\rm IB}^{(j)}\sqrt{\frac{n_{0}}{V}}\left[\frac{\left(\xi {\bf k}\right)^{2}}{\left(\xi {\bf k}\right)^{2}+2}\right]^{\frac{1}{4}}.
\end{equation}
After this procedure the Hamiltonian is transformed into

\begin{equation}
H_{\rm IB}^{(j)}=\sum_{{\bf k}\neq0}V_{{\bf k}}^{(j)}e^{i{\bf k}\left(x_{j}+d_{j}\right)}\left(b_{{\bf k}}+b_{-{\bf k}}^{\dagger}\right).
\end{equation}
Here, the couplings are
\begin{equation}
V_{{\bf k}}^{(j)}=g_{\rm IB}^{(j)}\sqrt{\frac{n_{0}}{V}}\left[\frac{\left(\xi {\bf k}\right)^{2}}{\left(\xi {\bf k}\right)^{2}+2}\right]^{\frac{1}{4}}.
\end{equation}
After this procedure the Hamiltonian is transformed into
%\begin{equation}
%\begin{array}{c}
\begin{align}
 \label{eq: Nonlinear eq two particles in a BEC}
&H=H_{\rm I}^{(1)}+H_{\rm I}^{(2)}+\sum_{{\bf k}\neq0}E_{{\bf k}}b_{{\bf k}}^{\dagger}b_{{\bf k}}+\sum_{{\bf k}\neq0}\left[V_{{\bf k}}^{(1)}e^{i{\bf k}\left({\bf x}_{1}+{\bf d}_{1}\right)}+V_{{\bf k}}^{(2)}e^{i{\bf k}\left({\bf x}_{2}+{\bf d}_{2}\right)}\right]\left(b_{{\bf k}}+b_{-{\bf k}}^{\dagger}\right).
\end{align}
%\end{array}
%\end{equation}
The above Hamiltonian with a non-linear interacting part is in general difficult to treat, and requires the usage of influence functional techniques \cite{Duarte2009}. 
To simplify the situation we will resort to the so called long-wave or dipole approximation. 
This is expressed by the assumption
\begin{equation}
{\bf k}\cdot {\bf x}_{1}\ll 1, \,\,\, {\bf k}\cdot  {\bf x}_{2}\ll 1, \label{eq:linear approximation}
\end{equation}
such that we can approximate the exponentials by a linear function.

