Using \eqref{eq:Delfsig}, the first order perturbative expression for the overlap can be read off:
%
\begin{equation}
\label{eq:Delfg}
\frac{g_{i,pert}}{2}=\frac{\xi F_{1,i}^{\sigma}}{\left(m_i^{(0)}\right)^2}\,,
\end{equation}
%
where the $m_i^{(0)}$ are the masses in the pre-quench theory, related to the post-quench masses by

\begin{eqnarray}
G_\mathrm{reg}(s) &=& \int_{-\infty}^{\infty}d\Delta~P_\Delta\int_{-\infty}^{\infty}dM~P_M~e^{i s L M^2/\Delta^2}\nonumber\\
&=&\int_{-\infty}^{\infty}dM~P_M~e^{-\sqrt{-2i s L M^2}/\sigma_\Delta}.
\end{eqnarray}
Our quantity of interest, $\mathcal{P}_{L\vert\phi\vert^2}$, is the inverse Fourier transform of $G_\mathrm{reg}(s)$,
\begin{equation}
\mathcal{P}_{L\vert\phi\vert^2}=\int_{-\infty}^{\infty}ds~e^{-i s L\vert\psi\vert^2}\int_{-\infty}^{\infty}dM~P_M~e^{-\vert M\vert\sqrt{-2i s L}/\sigma_\Delta},
\label{eq:invfourier}
\end{equation}
which can be recast as a series
\begin{equation}
\mathcal{P}_{L\vert\phi\vert^2}=\int_{-\infty}^{\infty}ds~e^{-i s L\vert\psi\vert^2}\sum_{k=0}^\infty \langle\vert M\vert^k\rangle (sL)^{k/2}\frac{(-2i)^{k/2}}{k!\,\sigma^k_\Delta}.
\end{equation}
In the thermodynamic limit, in the integral over $s$ in Eq.~\eqref{eq:invfourier}, the range of $s$ which contributes is such that $sL\vert\psi\vert^2\sim 1$. This implies that, if we are interested in the probability of the wavefunction intensity scaling as $L^{-\alpha}$, we must consider $s\sim L^{\alpha-1}$. With this scaling of $s$, the terms of the summation scale as $L^{k(\alpha-2\gamma_k)/2}$, where we denote $\langle\vert M\vert^k\rangle^{1/k}_P\sim L^{-\gamma_k}$.
Since, $\gamma_k>0$, the series is convergent if $\alpha/2<\mathrm{min}[\gamma_k]$. The distribution shown in Fig.~5(a) was found to have $\gamma_k$ as a non-decreasing function of $k$.
Hence for $\alpha<2\gamma_1$, the leading behavior in $\mathcal{P}_{L\vert\phi\vert^2}$ is
\begin{eqnarray}
\mathcal{P}_{L\vert\phi\vert^2}&\sim \frac{L^{-\gamma_1+1/2}}{(L\vert\phi\vert^2)^{3/2}}\int_{-\infty}^{\infty}&d(sL\vert\phi\vert^2)\bigg[e^{-i s L\vert\phi\vert^2}\times\nonumber\\
&&\left.(sL\vert\phi\vert^2)^{1/2}\frac{(-2i)^{1/2}}{\sigma_\Delta}\right],
\end{eqnarray}
which in terms of $\alpha$ can be expressed as
\begin{equation}
\mathcal{P}_{L\vert\phi\vert^2}\sim C_1 \frac{L^{-\gamma_1+1/2}}{(L\vert\phi\vert^2)^{3/2}}\sim C_1 \frac{L^{-\gamma_1+1/2}}{(L^{1-\alpha})^{3/2}},
\end{equation}
where $C_1$ depends at most logarithmically with $L$.
The normalization of the probability distribution and the wavefunction intensities put further bounds on $\alpha$.
\begin{itemize}
	\item Normalization of the distribution $\int_0^\infty d(L\vert\phi\vert^2)~\mathcal{P}_{L\vert\phi\vert^2}=1$ implies that the lower bound of $L\vert\phi\vert^2$ and hence the upper bound of $\alpha$ is given by $L^{-\gamma_1+1/2}L^{(\alpha_{max}-1)/2}\sim L^0$, which implies $\alpha_{max}=2\gamma_1$ .
	\item Normalization of the wavefunction $\int_0^\infty d(L\vert\phi\vert^2)~L\vert\phi\vert^2\mathcal{P}_{L\vert\phi\vert^2}=1$ implies that the upper bound of $L\vert\phi\vert^2$ and hence the lower bound of $\alpha$ is given by $L^{-\gamma_1+1/2}L^{(-\alpha_{min}+1)/2}\sim L^0$, which implies $\alpha_{min}=2(1-\gamma_1)$ .
\end{itemize}

