\braket{v_1 \dots v_N|w_1 \dots w_N} = (-1)^N \left(\frac{\prod_{i=1}^L \epsilon_i}{\prod_{a=1}^N v_a}\right) \left[\prod_{k=1}^{L-2N}\left(g^{-1}+1-k\right)\right]^{-1} \det J_L(\{v_a\},\{w_b\}),
